<script setup lang="ts">
import {ref,reactive,toRefs,onMounted,onUnmounted} from 'vue'
import {api} from './api'
import {ModelSettingsState} from './modelSettingsState'
import type {Profile} from './modelSettingsState'
const settings=reactive(new ModelSettingsState(api)), {config,saved,codex,models,catalogNote,profiles,activeId,editingId,name}=toRefs(settings)
const key=ref(''), manualCode=ref(''), loginMethod=ref<''|'device'|'browser'>(''), password=ref(''), error=ref(''), notice=ref(''), job=ref<any>(null), busy=ref(false), loading=ref(true)
const access=ref<any>({}), ownerPassword=ref(''), ownerConfirm=ref('')
const loginStages:Record<string,string>={starting:'正在启动授权',waiting_authorization:'等待浏览器或设备码授权',exchanging_token:'正在交换授权令牌',validating_credential:'正在校验授权凭据',saving_credential:'正在加密保存授权',completed:'授权已完成'}
const android=navigator.userAgent.includes('NihaixiaAndroid/')
let timer:ReturnType<typeof setTimeout>|undefined, oauthTimer:ReturnType<typeof setTimeout>|undefined, disposed=false
async function run(fn:()=>Promise<void>){error.value='';notice.value='';busy.value=true;try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function load(){try{const results=await Promise.allSettled([settings.load(),settings.loadProfiles(),api.request('/access/status').then(a=>{access.value=a})]);if(!settings.editingId&&settings.activeId){const p=settings.profiles.find(p=>p.id===settings.activeId);if(p)settings.selectForEdit(p)}const failed=results.find(r=>r.status==='rejected');if(failed?.status==='rejected')throw failed.reason;if(config.value.auth_mode==='codex'&&!models.value.length)await settings.loadModels()}finally{loading.value=false;if(codex.value.login?.status==='pending')scheduleOAuth()}}
function editProfile(p:Profile){key.value='';settings.selectForEdit(p);if(settings.config.auth_mode==='codex')void run(()=>settings.loadModels())}
function newDraft(){key.value='';settings.newDraft()}
async function save(){
 const created=!settings.editingId, wasActive=settings.activeId
 const p=await settings.saveProfile(key.value);key.value=''
 notice.value=p.key_cleanup_incomplete?'配置已保存，但旧的加密密钥文件未清理，请在本机检查文件权限。':created?'配置已创建，尚未设为当前；点击“设为当前”后新请求才会使用它。':p.id===wasActive?'配置已保存，新请求将使用更新后的设置；密钥输入已清空。':'配置已保存，但尚未设为当前；当前生效配置保持不变。'
}
async function useProfile(id:string){await settings.useProfile(id);notice.value='已设为当前配置，仅影响之后的新请求。'}
async function removeProfile(p:Profile){
 if(!confirm(`删除配置“${p.name}”？删除后不可恢复，不影响问诊记录和医学原件。`))return
 const wasActive=p.id===activeId.value
 await run(async()=>{if(p.id===editingId.value)key.value='';const result=await settings.deleteProfile(p.id);notice.value=result.key_cleanup_incomplete?'配置已移除，但部分加密密钥文件未清理，请检查本机文件权限。':wasActive?'已删除当前配置。现在没有当前配置，新模型请求会停止，且不会自动改用其他配置。删除配置不会退出共用的Codex账号。':'配置已删除。'})
}
async function poll(){job.value=await api.request(`/model/jobs/${job.value.id}`);if(['queued','running'].includes(job.value.status))timer=setTimeout(()=>run(poll),1000)}
async function test(){job.value=await api.post('/model/jobs',{purpose:'test'});await poll()}
function scheduleOAuth(){if(oauthTimer)clearTimeout(oauthTimer);if(!disposed)oauthTimer=setTimeout(()=>run(pollOAuth),1500)}
async function pollOAuth(){await settings.refreshCodex();if(codex.value.login?.status==='pending')scheduleOAuth();else{loginMethod.value='';manualCode.value='';if(codex.value.login?.status==='completed'){notice.value='Codex授权已保存在电脑端。请保存配置后测试连接。'}}}
async function startLogin(method:'device'|'browser'){loginMethod.value=method;manualCode.value='';await api.post('/model/codex/login',{method});await pollOAuth()}
async function cancelLogin(){await api.post(`/model/codex/login/${codex.value.login.id}/cancel`,{});manualCode.value='';loginMethod.value='';await pollOAuth()}
async function logoutCodex(){await api.post('/model/codex/logout',{});manualCode.value='';loginMethod.value='';await pollOAuth();notice.value='已移除本工作台的Codex授权。'}
function showManualCode(){const login=codex.value.login;return login?.status==='pending'&&!!login.auth_url&&(login.method==='browser'||loginMethod.value==='browser')}
async function submitManualCode(){
 const value=manualCode.value.trim()
 if(!/^http:\/\/(?:localhost|127\.0\.0\.1|\[::1\]):1455\/auth\/callback\?/i.test(value))throw Error('请粘贴以 http://localhost:1455/auth/callback? 开头的完整回调网址')
 await settings.submitLoginCode(value);manualCode.value='';notice.value='回调网址已提交，正在完成授权。'
}
async function copyDeviceCode(){const value=codex.value.login?.device_code?.code;if(!value)return;try{await navigator.clipboard.writeText(value);notice.value='设备码已复制，请粘贴到OpenAI设备授权页。'}catch{notice.value='无法自动复制，请手动选中设备码后复制。'}}
function refreshOnFocus(){if(!busy.value)void run(pollOAuth)}
async function setupAccess(){if(ownerPassword.value!==ownerConfirm.value)throw Error('两次访问密码不一致');await api.post('/access/setup',{password:ownerPassword.value});ownerPassword.value='';ownerConfirm.value='';await api.session();access.value=await api.request('/access/status');notice.value='访问密码已设置。可运行 start-lan.cmd 启用局域网。'}
async function logout(){await api.post('/access/logout',{});await api.session();window.dispatchEvent(new Event('tcm-logout'))}
async function backup(){if(android)throw Error('请在电脑网页下载备份');if(password.value.length<12)throw Error('备份密码至少 12 字符');const blob=await api.post<Blob>('/backup',{password:password.value});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`tcm-backup-${new Date().toISOString().slice(0,10)}.tcmbak`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);password.value='';notice.value='加密备份下载已发起。'}
onMounted(()=>{window.addEventListener('focus',refreshOnFocus);void run(load)});onUnmounted(()=>{disposed=true;manualCode.value='';window.removeEventListener('focus',refreshOnFocus);if(timer)clearTimeout(timer);if(oauthTimer)clearTimeout(oauthTimer)})
</script>
<template><section><div v-if="error" class="error-box" role="alert">{{error}}</div><div v-if="notice" class="notice" role="status">{{notice}}</div><div class="settings-grid"><div class="panel"><h2>模型服务</h2><p class="hint">只在点击发送或测试时请求模型。测试仅发送固定合成文本。</p>
<fieldset :disabled="loading||busy" style="border:0;padding:0;margin:0;min-width:0"><p v-if="loading" class="hint">正在加载模型配置……</p><div class="result-card" aria-label="当前生效的模型配置"><h3>当前生效配置</h3><p v-if="saved"><strong>{{saved.profile_name||'（未命名）'}}</strong> · {{saved.auth_mode==='codex'?'Codex账号授权':'API Key'}} · 模型：{{saved.model||'未设置'}} · {{saved.enabled?'已启用':'未启用'}}</p><p v-else>当前没有生效的配置；新的模型请求会停止，且不会自动改用其他配置。</p><p class="hint">所有Codex配置共用本工作台同一份Codex账号授权。删除配置不会退出该账号；如需退出请使用下方“退出Codex授权”。</p></div>
<h3>模型配置列表</h3><ul class="profile-list" aria-label="模型配置列表"><li v-for="p in profiles" :key="p.id"><label class="check"><input type="radio" name="profile-edit" :checked="editingId===p.id" @change="editProfile(p)">编辑 {{p.name}}</label><span class="hint">{{p.auth_mode==='codex'?'Codex账号':'API Key'}} · {{p.model||'未设置模型'}} · {{p.enabled?'已启用':'未启用'}}<template v-if="p.id===activeId"> · 当前生效</template></span><div class="button-row"><button :disabled="busy||p.id===activeId" @click="run(()=>useProfile(p.id))">设为当前</button><button :disabled="busy" @click="removeProfile(p)">删除</button></div></li></ul><p v-if="!profiles.length" class="hint">尚未保存任何配置。填写下方表单并保存即可新建。</p>
<div class="button-row"><button :disabled="busy" @click="newDraft">新建配置草稿</button></div>
<h3>{{editingId?'编辑所选配置':'新建配置草稿'}}</h3><p class="hint">正在编辑：{{editingId?(name||'未命名'):'新草稿'}}；当前生效：{{saved?.profile_name||'无'}}。保存不会自动设为当前；当前项只影响之后的新请求。</p>
<label>配置名称（必填，1–80字符）<input v-model="name" autocomplete="off" maxlength="80"></label>
<label>连接方式<select v-model="config.auth_mode" @change="key='';run(()=>settings.selectAuthMode(config.auth_mode))"><option value="api_key">API Key（兼容接口）</option><option value="codex">Codex账号授权</option></select></label>
<template v-if="config.auth_mode==='api_key'"><label>API基址<input v-model="config.base_url" type="url" placeholder="HTTPS 或 HTTP loopback"></label><label>新API密钥（留空保留现有密钥）<input v-model="key" type="password" autocomplete="new-password"></label><p class="hint">{{config.has_key?'已保存密钥（不会显示）':'尚未保存密钥'}}。此密钥仅属于当前配置并在电脑端加密保存；留空保存保留旧密钥；更换API地址或从Codex切回API时，请重新输入对应密钥。</p></template>
<div v-else class="result-card"><h3>Codex登录</h3><p>{{codex.logged_in?'本工作台已授权':'尚未授权'}}。所有Codex配置共用这份账号授权，授权令牌只在电脑端加密保存。</p><div class="button-row"><button :disabled="busy||codex.login?.status==='pending'" @click="run(()=>startLogin('device'))">设备码登录（推荐手机）</button><button v-if="!android" :disabled="busy||codex.login?.status==='pending'" @click="run(()=>startLogin('browser'))">电脑浏览器登录</button><button :disabled="busy" @click="run(pollOAuth)">刷新授权状态</button></div><p v-if="codex.login?.stage" role="status">授权阶段：{{loginStages[codex.login.stage]||'正在处理授权'}}</p><p class="hint">设备码在OpenAI官方页面完成，方向是工作台到设备授权页；浏览器回调方式请在运行服务的这台电脑上完成，回调会回到工作台。登录不等于账号有可用额度。</p>
<template v-if="codex.login?.status==='pending'"><p>等待授权完成……</p><p v-if="codex.login.device_code">设备码：<strong class="device-code">{{codex.login.device_code.code}}</strong> <button type="button" :disabled="busy" @click="copyDeviceCode">复制设备码</button></p><p v-if="codex.login.auth_url||codex.login.device_code?.url"><a :href="codex.login.auth_url||codex.login.device_code?.url" target="_blank" rel="noopener noreferrer">打开OpenAI授权页面</a></p>
<template v-if="showManualCode()"><label>粘贴当前授权后的完整回调网址（http://localhost:1455/auth/callback?...）<input v-model="manualCode" type="url" autocomplete="off" spellcheck="false" placeholder="http://localhost:1455/auth/callback?code=...&state=..."></label><p class="hint">只粘贴授权完成或失败后地址栏中的完整回调网址；请勿粘贴密码、request_id或账号ID。输入不会保存，提交成功、取消或离开设置后清空。</p><button :disabled="busy||!manualCode.trim()" @click="run(submitManualCode)">提交回调网址</button></template>
<button :disabled="busy" @click="run(cancelLogin)">取消本次授权</button></template><p v-if="codex.login?.error" class="warning">{{codex.login.error}}</p><p v-if="codex.credential_error" class="warning">{{codex.credential_error}}</p><button v-if="codex.logged_in||codex.credential_error" :disabled="busy" @click="run(logoutCodex)">{{codex.credential_error?'清除不可用授权':'退出Codex授权'}}</button></div>
<label v-if="config.auth_mode==='codex'">Codex模型目录<select v-model="config.model"><option value="">请选择模型，或在下方填写ID</option><option v-if="config.model&&!models.some(m=>m.id===config.model)" :value="config.model">自定义：{{config.model}}</option><option v-for="m in models" :key="m.id" :value="m.id">{{m.name}} · {{m.id}}</option></select></label><label>{{config.auth_mode==='codex'?'模型 ID（也可手动填写）':'模型 ID'}}<input v-model="config.model" autocomplete="off" maxlength="200"></label><template v-if="config.auth_mode==='codex'"><button :disabled="busy" @click="run(()=>settings.loadModels())">刷新SDK模型目录</button><p class="hint">{{catalogNote||'模型目录是SDK信息，账号是否可用需实际测试。'}}</p></template>
<label class="check"><input type="checkbox" v-model="config.enabled">启用模型服务</label><label class="check"><input type="checkbox" :checked="config.allow_external && config.allow_evidence" @change="config.allow_external=($event.target as HTMLInputElement).checked;config.allow_evidence=config.allow_external">允许发送必要症状和书证至所选服务</label><div class="button-row"><button class="primary" :disabled="busy" @click="run(save)">保存此配置</button><button :disabled="busy" @click="run(test)">测试当前生效配置</button></div><div v-if="job" class="result-card"><strong>连接测试 · {{job.status}}</strong><pre>{{job.text||'暂无输出'}}</pre><p v-if="job.error" class="warning">{{job.error}}</p></div></fieldset></div>
<div><div class="panel"><h2>工作台访问与多端</h2><p>网页与安卓连接同一台电脑，使用同一书库和问诊记录。电脑需保持运行。</p><form v-if="access.setup_allowed" @submit.prevent="run(setupAccess)"><label>设置访问密码（12至256字符）<input v-model="ownerPassword" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label>再次输入<input v-model="ownerConfirm" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><button :disabled="busy">保存访问密码</button></form><template v-else-if="access.configured"><p>访问密码已设置，当前设备已登录。</p><button :disabled="busy" @click="run(logout)">退出当前设备</button></template><p class="hint">在电脑运行 start-lan.cmd 查看HTTPS局域网地址。安卓需安装为本机CA构建的APK；网页需先核对并信任本机CA。详细步骤见项目使用说明。</p></div>
<div class="panel"><h2>加密备份</h2><p>包含数据库和登记原件；模型授权、访问密码和局域网证书需另行配置。</p><p v-if="android" class="hint">请在电脑网页下载备份和大型原件。安卓支持书库原文、页面图像和问诊。</p><template v-else><label>备份密码（至少12字符）<input v-model="password" type="password" autocomplete="new-password"></label><button :disabled="busy||password.length<12" @click="run(backup)">下载加密备份</button></template><p class="hint">请保管密码；恢复目标目录必须为空。</p></div></div></div></section></template>
